// 获取当前语言
const getLocale = (): Locale => {
  const saved = localStorage.getItem('wiki_locale') as Locale
  return saved || 'zh'
}

/** 与 localeStore.localeMap 一致，供请求头 Accept-Language 等使用 */
const LOCALE_BCP47: Record<Locale, string> = {
  zh: 'zh-CN',
  en: 'en-US',
  ko: 'ko-KR',
  de: 'de-DE',
  ja: 'ja-JP',
  fr: 'fr-FR'
}

/** 当前语言的 BCP 47 标签（如 zh-CN），用于 HTTP Accept-Language */
const getLocaleBcp47 = (): string => {
  const loc = getLocale()
  return LOCALE_BCP47[loc] || 'zh-CN'
}

// 设置语言
const setLocale = (locale: Locale) => {
  localStorage.setItem('wiki_locale', locale)
}

// 翻译函数
const t = (key: string, params?: Record<string, string>): string => {
  const locale = getLocale()
  let message = messages[locale][key] || messages.zh[key] || key
  
  // 替换参数
  if (params) {
    Object.keys(params).forEach(param => {
      const value = params[param]
      if (value !== undefined) {
        message = message.replace(`{${param}}`, value)
      }
    })
  }
  
  return message
}

// 获取当前语言名称
const getLocaleName = (): string => {
  const locale = getLocale()
  const localeNames: Record<Locale, string> = {
    zh: '中文',
    en: 'English',
    ko: '한국어',
    de: 'Deutsch',
    ja: '日本語',
    fr: 'Français'
  }
  return localeNames[locale] || '中文'
}

// 切换语言（循环切换所有语言）
const toggleLocale = (): Locale => {
  const locales: Locale[] = ['zh', 'en', 'ko', 'de', 'ja', 'fr']
  const current = getLocale()
  const currentIndex = locales.indexOf(current)
  const nextIndex = currentIndex >= 0 ? (currentIndex + 1) % locales.length : 0
  const next: Locale = locales[nextIndex] || 'zh'
  setLocale(next)
  return next
}

export type { Locale }
export { t, getLocale, setLocale, getLocaleName, toggleLocale, getLocaleBcp47 }
